model Task {
  id: ID
  title: String min=1
  done: Bool = false
}

component TaskRow(task: Task, onRemove: Fn) {
  row gap=2 align=center {
    checkbox task.done
    text task.title muted=task.done
    button "x" small -> onRemove(task.id)
  }
}

page Home "/" {
  state draft = ""
  state tasks: Task[] = []
  computed pending = tasks.filter(t => !t.done)
  fn add() {
    if draft.trim() == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: draft.trim(), done: false })
    draft = ""
  }

  column gap=4 pad=4 {
    title "Tareas"
    row gap=2 {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    for t in tasks key t.id {
      TaskRow task=t onRemove=(id => tasks = tasks.filter(x => x.id != id))
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending.length} pendientes` small
    }
  }
}

test "agrega una tarea con Enter" {
  fill "¿Qué hay que hacer?" "Leche"
  press "¿Qué hay que hacer?" "Enter"
  see "Leche"
  see "1 pendientes"
}

