model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  state products: Product[] = [
    { id: "p1", name: "Camiseta", price: 12.5 },
    { id: "p2", name: "Taza", price: 7.99 },
    { id: "p3", name: "Gorra", price: 15 }
  ]
  state cart: CartItem[] = []
  computed total = cart.reduce((s, c) => s + c.price * c.qty, 0)
  computed count = cart.reduce((s, c) => s + c.qty, 0)

  fn add(p) {
    let existing = cart.find(c => c.id == p.id)
    if existing {
      cart = cart.map(c => c.id == p.id ? { ...c, qty: c.qty + 1 } : c)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn inc(id) {
    cart = cart.map(c => c.id == id ? { ...c, qty: c.qty + 1 } : c)
  }

  fn dec(id) {
    cart = cart
      .map(c => c.id == id ? { ...c, qty: c.qty - 1 } : c)
      .filter(c => c.qty > 0)
  }

  column gap=4 pad=4 {
    title "Tienda"
    card gap=2 pad=3 {
      text "Productos" bold
      for p in products key p.id {
        row gap=2 align=center justify=between {
          text p.name
          text `$${p.price.toFixed(2)}` muted
          button "Agregar" primary small -> add(p)
        }
      }
    }
    card gap=2 pad=3 {
      text `Carrito (${count})` bold
      if cart.length == 0 {
        text "El carrito está vacío" muted
      } else {
        for c in cart key c.id {
          row gap=2 align=center justify=between {
            text c.name
            row gap=2 align=center {
              button "-" small -> dec(c.id)
              text `${c.qty}`
              button "+" small -> inc(c.id)
            }
            text `$${(c.price * c.qty).toFixed(2)}`
          }
        }
      }
      divider
      text `Total: $${total.toFixed(2)}` bold large
    }
  }
}

test "agrega y quita productos" {
  see "Total: $0.00"
  click "Agregar" 0
  click "Agregar" 0
  see "Total: $25.00"
  click "Agregar" 1
  see "Total: $32.99"
  click "-" 1
  see "Total: $25.00"
  click "-" 0
  click "-" 0
  see "El carrito está vacío"
}

