model Usuario {
  id: ID
  name: String min=1
  email: String
}

api usuarios: Usuario

page Home "/" {
  state nombre = ""
  state email = ""
  state error = ""
  data usuarios = api.usuarios.list()

  fn agregar() {
    error = ""
    let n = nombre.trim()
    let e = email.trim()
    if !e.includes("@") {
      error = "Email inválido"
      return
    }
    if n == "" {
      error = "Nombre requerido"
      return
    }
    try {
      await api.usuarios.create({ name: n, email: e })
      nombre = ""
      email = ""
    } catch (err) {
      error = err.message
    }
  }

  fn borrar(id) {
    try {
      await api.usuarios.remove(id)
    } catch (err) {
      error = err.message
    }
  }

  column gap=4 pad=4 {
    title "Usuarios"
    row gap=2 align=center {
      input nombre placeholder="Nombre" -> agregar()
      input email placeholder="Email" -> agregar()
      button "Agregar" primary -> agregar()
    }
    if error != "" {
      text error danger
    }
    if usuarios.length == 0 {
      text "No hay usuarios" muted
    } else {
      for u in usuarios key u.id {
        row gap=2 align=center {
          text u.name bold
          text u.email
          button "Borrar" small danger -> borrar(u.id)
        }
      }
    }
  }
}

