model Usuario {
  id: ID
  name: String
  email: String
}

api usuarios: Usuario

page Home "/" {
  state nombre = ""
  state email = ""
  state error = ""
  data lista = api.usuarios.list()

  fn agregar() {
    error = ""
    if !email.includes("@") {
      error = "Email inválido"
      return
    }
    try {
      await api.usuarios.create({ name: nombre.trim(), email: email.trim() })
      nombre = ""
      email = ""
    } catch (e) {
      error = e.message
    }
  }

  fn borrar(id) {
    try {
      await api.usuarios.remove(id)
    } catch (e) {
      error = e.message
    }
  }

  column gap=4 pad=4 {
    title "Usuarios"
    row gap=2 align=center {
      input nombre placeholder="Nombre" -> agregar()
      input email placeholder="Email" -> agregar()
      button "Agregar" primary -> agregar()
    }
    if error != "" {
      text error danger
    }
    if lista.length == 0 {
      text "No hay usuarios" muted
    } else {
      for u in lista key u.id {
        card pad=2 {
          row gap=2 align=center justify=between {
            column gap=1 {
              text u.name bold
              text u.email muted
            }
            button "Borrar" danger small -> borrar(u.id)
          }
        }
      }
    }
  }
}

