model Item {
  id: ID
  name: String min=1
  bought: Bool = false
}

api items: Item

page Home "/" {
  state draft = ""
  state error = ""
  data items = api.items.list()
  computed pending = (items ?? []).filter(i => !i.bought)

  fn add() {
    let name = draft.trim()
    if name == "" { return }
    try {
      await api.items.create({ name: name, bought: false })
      draft = ""
      error = ""
    } catch (e) {
      error = e.message
    }
  }

  fn markBought(id) {
    try {
      await api.items.update(id, { bought: true })
    } catch (e) {
      error = e.message
    }
  }

  fn removeItem(id) {
    try {
      await api.items.remove(id)
    } catch (e) {
      error = e.message
    }
  }

  column gap=4 pad=4 {
    title "Lista de compras"
    text `${pending.length} por comprar`
    row gap=2 {
      input draft placeholder="Producto" -> add()
      button "Agregar" primary -> add()
    }
    if error != "" {
      text error danger
    }
    for it in (items ?? []) key it.id {
      row gap=2 align=center {
        text it.name muted=it.bought
        if it.bought {
          text "✓" bold
        }
        button "Comprado" small disabled=it.bought -> markBought(it.id)
        button "Borrar" small danger -> removeItem(it.id)
      }
    }
  }
}

