model Author {
  id: ID
  name: String min=1
}

model Post {
  id: ID
  title: String min=1
  author: Author
}

api authors: Author
api posts: Post

page Home "/" {
  data authors = api.authors.list()
  data posts = api.posts.list()
  state authorName = ""
  state postTitle = ""
  state selectedAuthor = ""
  state msg = ""

  async fn createAuthor() {
    msg = ""
    if authorName.trim() == "" { return }
    try {
      await api.authors.create({ name: authorName.trim() })
      authorName = ""
    } catch (e) {
      msg = e.message
    }
  }

  async fn publish() {
    msg = ""
    if postTitle.trim() == "" { return }
    const a = authors.find(x => x.name == selectedAuthor) ?? authors[0]
    if !a {
      msg = "Primero creá un autor"
      return
    }
    try {
      await api.posts.create({ title: postTitle.trim(), author: a.id })
      postTitle = ""
    } catch (e) {
      msg = e.message
    }
  }

  async fn removeAuthor(id) {
    msg = ""
    const hasPosts = posts.some(p => (p.author?.id ?? p.author) == id)
    if hasPosts {
      msg = "El autor tiene posts"
      return
    }
    try {
      await api.authors.remove(id)
    } catch (e) {
      msg = e.message
    }
  }

  column gap=4 pad=4 {
    title "Blog"
    if msg != "" {
      text msg danger
    }

    card gap=2 pad=3 {
      title "Autores" tag=h2
      row gap=2 {
        input authorName placeholder="Autor" -> createAuthor()
        button "Crear autor" primary -> createAuthor()
      }
      for a in authors key a.id {
        row gap=2 align=center {
          text a.name
          button "Borrar autor" small danger -> removeAuthor(a.id)
        }
      }
    }

    card gap=2 pad=3 {
      title "Nuevo post" tag=h2
      row gap=2 {
        input postTitle placeholder="Título" -> publish()
        select selectedAuthor options=(authors.map(a => a.name)) label="Autor del post"
        button "Publicar" primary -> publish()
      }
    }

    column gap=2 {
      title "Posts" tag=h2
      if posts.length == 0 {
        text "Todavía no hay posts" muted
      } else {
        for p in posts key p.id {
          card gap=1 pad=3 {
            text p.title bold
            text `por ${p.author?.name ?? ""}` muted small
          }
        }
      }
    }
  }
}

