model Product {
  id: ID
  name: String min=3
  code: String min=1 unique
  price: Number min=0
}

api products: Product

page Home "/" {
  state nombre = ""
  state codigo = ""
  state precio = ""
  state error = ""
  data products = api.products.list()

  fn mensaje(e) {
    if e.status == 409 { return "Código repetido" }
    let field = e.details?.field
    if field == "name" { return "Nombre muy corto" }
    if field == "code" { return "Código repetido" }
    if field == "price" { return "Precio inválido" }
    return e.message
  }

  fn guardar() {
    error = ""
    let p = Number(precio)
    if precio.toString().trim() == "" || isNaN(p) {
      error = "Precio inválido"
      return
    }
    try {
      await api.products.create({ name: nombre.trim(), code: codigo.trim(), price: p })
      nombre = ""
      codigo = ""
      precio = ""
    } catch (e) {
      error = mensaje(e)
    }
  }

  column gap=4 pad=4 {
    title "Registro de productos"
    row gap=2 wrap {
      input nombre placeholder="Nombre"
      input codigo placeholder="Código"
      input precio placeholder="Precio" -> guardar()
      button "Guardar" primary -> guardar()
    }
    if error != "" {
      text error danger
    }
    if (products ?? []).length == 0 {
      text "No hay productos" muted
    } else {
      list {
        for p in products key p.id {
          item `${p.name} — ${p.code}`
        }
      }
    }
  }
}

