page Home "/" {
  data products = api.products.list()
  state name = ""
  state code = ""
  state price = ""
  state error = ""

  fn messageFor(e) {
    if e.status == 409 { return "Código repetido" }
    const field = e.details?.field
    if field == "name" { return "Nombre muy corto" }
    if field == "price" { return "Precio inválido" }
    if field == "code" { return "Código repetido" }
    return e.message ?? "Error al guardar"
  }

  fn save() {
    error = ""
    try {
      await api.products.create({ name: name.trim(), code: code.trim(), price: Number(price) })
      name = ""
      code = ""
      price = ""
    } catch (e) {
      error = messageFor(e)
    }
  }

  column gap=4 pad=4 {
    title "Registro de productos"
    row gap=2 wrap {
      input name placeholder="Nombre"
      input code placeholder="Código"
      input price placeholder="Precio" type=number
      button "Guardar" primary -> save()
    }
    if error != "" {
      text error danger
    }
    if products.length == 0 {
      text "No hay productos" muted
    } else {
      list {
        for p in products key p.id {
          item {
            row gap=2 {
              text p.name bold
              text p.code muted
            }
          }
        }
      }
    }
  }
}

