model Profile {
  id: ID
  photo: File?
}

api profiles: Profile

page Perfil "/" {
  data profiles = api.profiles.list({ limit: 1 })
  state picked: File? = null
  state uploading = false
  state msg = ""

  fn subir() {
    if !picked {
      msg = "Elegí una foto primero"
      return
    }
    uploading = true
    msg = ""
    try {
      if profiles.length > 0 {
        await api.profiles.update(profiles[0].id, { photo: picked })
      } else {
        await api.profiles.create({ photo: picked })
      }
      picked = null
      msg = "Foto subida"
    } catch (e) {
      msg = e.message
    }
    uploading = false
  }

  column gap=4 pad=4 {
    title "Mi perfil" tag=h1
    card gap=3 pad=4 {
      file picked accept="image/*"
      row gap=2 align=center {
        button (uploading ? "Subiendo..." : "Subir") primary disabled=(uploading || !picked) -> subir()
        if uploading {
          spinner
        }
      }
      if msg != "" {
        text msg small muted
      }
    }
    if profiles.length > 0 && profiles[0].photo {
      image (profiles[0].photo?.url ?? "") alt="Foto de perfil" width=240
    } else {
      text "Todavía no subiste ninguna foto" muted
    }
  }
}

