page ProfilePage "/" {
  state picked: File? = null
  state msg = ""
  state uploading = false
  data profiles = api.profiles.list()
  computed current = profiles.find(p => true)

  fn upload() {
    if !picked { return }
    uploading = true
    msg = ""
    try {
      if current {
        await api.profiles.update(current.id, { photo: picked })
      } else {
        await api.profiles.create({ photo: picked })
      }
      msg = "Foto subida"
      picked = null
    } catch (e) {
      msg = e.message
    }
    uploading = false
  }

  column gap=4 pad=4 {
    title "Mi perfil" tag=h1
    card gap=3 pad=4 {
      file picked accept="image/*"
      button (uploading ? "Subiendo..." : "Subir") primary disabled=(!picked || uploading) -> upload()
      if msg != "" {
        text msg small
      }
    }
    if current && current.photo {
      image current.photo.url alt="Foto de perfil" width=240
    } else {
      text "Todavía no subiste ninguna foto" muted
    }
  }
}

