export const W = 400;
export const H = 300;
export const R = 10;
export const GRAVITY = 0.2;

export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
  color: string;
}

const COLORS = ["#e63946", "#457b9d", "#2a9d8f", "#f4a261", "#9b5de5", "#e9c46a", "#06d6a0"];

export function make(existing: Ball[] = []): Ball {
  let x = 0;
  let y = 0;
  for (let attempt = 0; attempt < 50; attempt++) {
    x = R + Math.random() * (W - 2 * R);
    y = R + Math.random() * (H - 2 * R);
    const ok = existing.every((b) => Math.hypot(b.x - x, b.y - y) >= b.r + R);
    if (ok) break;
  }
  return {
    x,
    y,
    vx: (Math.random() * 2 - 1) * 4,
    vy: (Math.random() * 2 - 1) * 4,
    r: R,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeMany(n: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(make(balls));
  return balls;
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;

    if (b.x < b.r) {
      b.x = b.r;
      b.vx = Math.abs(b.vx);
    } else if (b.x > W - b.r) {
      b.x = W - b.r;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y < b.r) {
      b.y = b.r;
      b.vy = Math.abs(b.vy);
    } else if (b.y > H - b.r) {
      b.y = H - b.r;
      b.vy = -Math.abs(b.vy);
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      const minDist = a.r + b.r;
      if (dist < minDist) {
        // separar para que no queden superpuestas
        const nx = dist > 0 ? dx / dist : 1;
        const ny = dist > 0 ? dy / dist : 0;
        const overlap = (minDist - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;

        // solo intercambiar si se acercan
        const rvx = b.vx - a.vx;
        const rvy = b.vy - a.vy;
        if (rvx * nx + rvy * ny < 0) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
      }
    }
  }

  // asegurar que nadie quede fuera tras la separación
  for (const b of balls) {
    b.x = Math.min(Math.max(b.x, b.r), W - b.r);
    b.y = Math.min(Math.max(b.y, b.r), H - b.r);
  }
}

export function draw(cv: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!cv) return;
  const ctx = cv.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = "#f8f9fa";
  ctx.fillRect(0, 0, cv.width, cv.height);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

