page Sim "/" {
  state count = 0
  state frames = 0
  state paused = false
  ref cv
  ref balls
  ref raf

  fn tick() {
    if !paused {
      step(balls)
      draw(cv, balls)
      frames++
    }
    raf = requestAnimationFrame(tick)
  }

  fn add() {
