export const W = 400;
export const H = 300;
export const R = 10;
export const GRAVITY = 0.2;

export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
  color: string;
}

const COLORS = ["#e74c3c", "#3498db", "#2ecc71", "#f1c40f", "#9b59b6", "#e67e22", "#1abc9c"];

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function make(existing: Ball[] = []): Ball {
  let x = rand(R, W - R);
  let y = rand(R, H - R);
  for (let attempt = 0; attempt < 50; attempt++) {
    const ok = existing.every((b) => Math.hypot(b.x - x, b.y - y) >= b.r + R);
    if (ok) break;
    x = rand(R, W - R);
    y = rand(R, H - R);
  }
  return {
    x,
    y,
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    r: R,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeMany(n: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(make(balls));
  return balls;
}

function clampToWalls(b: Ball): void {
  if (b.x < b.r) {
    b.x = b.r;
    b.vx = Math.abs(b.vx);
  } else if (b.x > W - b.r) {
    b.x = W - b.r;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y < b.r) {
    b.y = b.r;
    b.vy = Math.abs(b.vy);
  } else if (b.y > H - b.r) {
    b.y = H - b.r;
    b.vy = -Math.abs(b.vy);
  }
}

export function step(balls: Ball[]): void {
  // gravedad y movimiento
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;
    clampToWalls(b);
  }

  // colisiones entre pelotas (masas iguales: intercambio de velocidades)
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let dist = Math.hypot(dx, dy);
      const minDist = a.r + b.r;
      if (dist < minDist) {
        if (dist === 0) {
          dx = 1;
          dy = 0;
          dist = 1;
        }
        const nx = dx / dist;
        const ny = dy / dist;
        // separar para que no queden superpuestas
        const overlap = (minDist - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        // intercambiar velocidades solo si se acercan
        const approaching = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny < 0;
        if (approaching) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
      }
    }
  }

  // garantizar que ninguna pelota quede fuera del canvas
  for (const b of balls) clampToWalls(b);
}

export function draw(canvas: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!canvas || !canvas.getContext) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#111827";
  ctx.fillRect(0, 0, W, H);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

