model Vote {
  id: ID
  choice: String match="^(perros|gatos)$"
}

api votes: Vote

server fn stats() {
  const all = db.votes.list()
  let dogs = 0
  let cats = 0
  for (const v of all) {
    if v.choice == "perros" { dogs++ }
    else if v.choice == "gatos" { cats++ }
  }
  const total = dogs + cats
  const dogsPct = total == 0 ? 0 : Math.round((dogs * 100) / total)
  const catsPct = total == 0 ? 0 : Math.round((cats * 100) / total)
  return { dogs, cats, dogsPct, catsPct, total }
}

server fn vote(choice) {
  if choice != "perros" && choice != "gatos" {
    fail("Opción inválida")
  }
  db.votes.create({ choice: choice })
  return true
}

server fn reset() {
  let rows = db.votes.list()
  while (rows.length > 0) {
    for (const v of rows) {
      db.votes.remove(v.id)
    }
    rows = db.votes.list()
  }
  return true
}

page Home "/" {
  state results: Any = { dogs: 0, cats: 0, dogsPct: 0, catsPct: 0, total: 0 }
  state loading = true
  state busy = false
  state error = ""

  fn refresh() {
    try {
      results = await server.stats()
      error = ""
    } catch (e) {
      error = e.message
    }
    loading = false
  }

  fn castVote(choice) {
    if busy { return }
    busy = true
    try {
      await server.vote(choice)
      await refresh()
    } catch (e) {
      error = e.message
    }
    busy = false
  }

  fn resetAll() {
    if busy { return }
    busy = true
    try {
      await server.reset()
      await refresh()
    } catch (e) {
      error = e.message
    }
    busy = false
  }

  mount {
    refresh()
  }

  column gap=4 pad=6 {
    title "¿Perros o gatos?" tag=h1
    row gap=2 wrap {
      button "Votar Perros" primary disabled=busy -> castVote("perros")
      button "Votar Gatos" primary disabled=busy -> castVote("gatos")
    }
    if loading {
      spinner
    } else {
      card gap=2 pad=4 {
        text `Perros: ${results.dogsPct}% (${results.dogs} votos)` large
        text `Gatos: ${results.catsPct}% (${results.cats} votos)` large
        text `Total: ${results.total} votos` muted small
      }
    }
    if error != "" {
      text error danger
    }
    button "Reiniciar" danger disabled=busy -> resetAll()
  }
}

model Vote {
  id: ID
  choice: String min=1
}

api votes: Vote

server fn results() {
  const all = db.votes.list()
  const perros = all.filter(v => v.choice == "perros").length
  const gatos = all.filter(v => v.choice == "gatos").length
  const total = perros + gatos
  const perrosPct = total == 0 ? 0 : Math.round((perros * 100) / total)
  const gatosPct = total == 0 ? 0 : Math.round((gatos * 100) / total)
  return { perros, gatos, perrosPct, gatosPct, total }
}

server fn vote(choice) {
  if (choice != "perros" && choice != "gatos") {
    fail("Opción inválida")
  }
  db.votes.create({ choice })
  return true
}

server fn reset() {
  const all = db.votes.list()
  for (const v of all) {
    db.votes.remove(v.id)
  }
  return true
}

page Home "/" {
  state perros = 0
  state gatos = 0
  state perrosPct = 0
  state gatosPct = 0
  state busy = false
  state error = ""

  fn refresh() {
    return server.results().then(r => {
      perros = r.perros
      gatos = r.gatos
      perrosPct = r.perrosPct
      gatosPct = r.gatosPct
    })
  }

  fn votar(choice) {
    busy = true
    error = ""
    server.vote(choice)
      .then(() => refresh())
      .catch(e => { error = e.message })
      .finally(() => { busy = false })
  }

  fn reiniciar() {
    busy = true
    error = ""
    server.reset()
      .then(() => refresh())
      .catch(e => { error = e.message })
      .finally(() => { busy = false })
  }

  mount {
    refresh().catch(e => { error = e.message })
  }

  column gap=4 pad=4 {
    title "Encuesta: ¿Perros o Gatos?" tag=h1
    row gap=2 {
      button "Votar Perros" primary disabled=busy -> votar("perros")
      button "Votar Gatos" primary disabled=busy -> votar("gatos")
    }
    card gap=2 pad=4 {
      text `Perros: ${perrosPct}% (${perros} votos)` large
      text `Gatos: ${gatosPct}% (${gatos} votos)` large
    }
