        msg = e.message
      }
    }
    if my == reqId {
      loading = false
    }
  }

  fn search(v) {
    q = v
    page = 0
    load()
  }

  fn prev() {
    if page > 0 {
      page = page - 1
      load()
    }
  }

  fn next() {
    if (page + 1) * 5 < total {
      page = page + 1
      load()
    }
  }

