    { id: 1, name: "Alfa", amount: 10, active: true },
    { id: 2, name: "Beta", amount: 20, active: true },
    { id: 3, name: "Gama", amount: 30, active: false }
  ]
  fn add(name, amount) {
    items.push({ id: Date.now(), name, amount, active: true })
  }

  column gap=2 {
    title "Empleados"
    EmployeesForm onAdd=add
    EmployeesList items=items
  }
}

component EmployeesList(items: Item[]) {
  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        EmployeesRow item=item
      }
    }
  }
}

component EmployeesRow(item: Item) {
  row gap=2 {
    text item.name bold
    if !item.active {
      text "(inactivo)" muted
    }
    text `Sueldo: ${item.amount}`
    button "Alternar" small -> item.active = !item.active
  }
}

